#include <iostream>
#include <map>
#include <print>
#include <string>
#include <vector>

struct Style {
    std::string name;
    int font = 0;
};

struct Doc {
    std::vector<std::string> lines;
    const Style *style = nullptr;
};

int main() {
    std::map<std::string, Style> styles;
    std::map<std::string, Doc> docs;
    std::string command, a;
    while (std::cin >> command >> a) {
        if (command == "style") {
            int font;
            std::cin >> font;
            Style &s = styles[a];
            s.name = a;
            s.font = font;
        } else if (command == "doc") {
            std::string s;
            std::cin >> s;
            docs.insert_or_assign(a, Doc{{}, &styles.at(s)});
        } else if (command == "copy") {
            std::string from;
            std::cin >> from;
            const Doc copy = docs.at(from);
            docs.insert_or_assign(a, copy);
        } else if (command == "line") {
            std::string text;
            std::cin >> text;
            docs.at(a).lines.push_back(text);
        } else {
            const Doc &d = docs.at(a);
            std::println("{}: {} строк, стиль {}, шрифт {}", a, d.lines.size(), d.style->name, d.style->font);
        }
    }
    return 0;
}

