#include <algorithm>
#include <iostream>
#include <print>
#include <string>

class Image {
public:
    Image(int w, int h, int fill) : w_(w), h_(h), pixels_(new int[w * h]) {
        std::fill_n(pixels_, w_ * h_, fill);
    }
    ~Image() {
        delete[] pixels_;
    }

    void paint(int x, int y, int value) {
        pixels_[y * w_ + x] = value;
    }

    int width() const {
        return w_;
    }
    int height() const {
        return h_;
    }

    long long brightness() const {
        long long sum = 0;
        for (int i = 0; i < w_ * h_; ++i) {
            sum += pixels_[i];
        }
        return sum / (w_ * h_);
    }

private:
    int w_, h_;
    int *pixels_;
};

void report(Image img) {
    std::println("{}x{}, средняя яркость {}", img.width(), img.height(), img.brightness());
}

int main() {
    int w, h, fill;
    std::cin >> w >> h >> fill;
    Image img(w, h, fill);
    std::string command;
    while (std::cin >> command) {
        if (command == "paint") {
            int x, y, v;
            std::cin >> x >> y >> v;
            img.paint(x, y, v);
        } else {
            report(img);
        }
    }
    return 0;
}

